def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            nb=[g[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=y<h and 0<=x<w]
            if g[r][c] not in nb:
                ct=__import__('collections').Counter(nb)
                m=max(ct.values())
                out[r][c]=max(v for v in ct if ct[v]==m)
    return out
